using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations:RefCounted
{
    private readonly ActorInspectorStateOperations _state=new();
    private static T Ui<T>(Control owner,string name) where T:GodotObject=>owner.Get(name).AsGodotObject() as T??throw new InvalidOperationException(name);
    public void build_navigation(Control owner)
    {
        var main=Ui<HBoxContainer>(owner,"main_tabs");main.Name="InspectorMainTabs";main.AddThemeConstantOverride("separation",3);owner.AddChild(main);var group=new ButtonGroup();var buttons=owner.Get("_main_buttons").AsGodotDictionary();foreach(string title in new[]{"Actor","Properties"}){var button=new Button{Name="Inspector"+title+"Tab",Text=title,ToggleMode=true,ButtonGroup=group,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};style_navigation_button(button,false);main.AddChild(button);buttons[title]=button;button.Pressed+=()=>select_main_tab(owner,title);}var identity=Ui<VBoxContainer>(owner,"identity_fields");identity.Name="InspectorIdentity";owner.AddChild(identity);var body=new HBoxContainer{Name="InspectorBody",SizeFlagsVertical=Control.SizeFlags.ExpandFill};body.AddThemeConstantOverride("separation",7);owner.AddChild(body);var rail=Ui<ScrollContainer>(owner,"section_scroll");rail.Name="InspectorSectionRail";rail.HorizontalScrollMode=ScrollContainer.ScrollMode.Disabled;rail.SizeFlagsVertical=Control.SizeFlags.ExpandFill;rail.CustomMinimumSize=new Vector2(72,0);body.AddChild(rail);var tabs=Ui<VBoxContainer>(owner,"section_tabs");tabs.Name="InspectorSectionTabs";tabs.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;tabs.AddThemeConstantOverride("separation",3);rail.AddChild(tabs);var content=Ui<ScrollContainer>(owner,"content_scroll");content.Name="InspectorContentScroll";content.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;content.SizeFlagsVertical=Control.SizeFlags.ExpandFill;content.HorizontalScrollMode=ScrollContainer.ScrollMode.Auto;body.AddChild(content);owner.Resized+=()=>rail.CustomMinimumSize=new Vector2(Math.Clamp(owner.Size.X*.24f,58,104),rail.CustomMinimumSize.Y);
    }
    public void style_navigation_button(Button button,bool side)
    {
        button.CustomMinimumSize=new Vector2(button.CustomMinimumSize.X,30);button.ClipText=true;button.TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis;button.AddThemeFontSizeOverride("font_size",13);foreach(string variant in new[]{"normal","hover","pressed","hover_pressed"}){bool selected=variant is "pressed" or "hover_pressed";var style=new StyleBoxFlat{BgColor=new Color(selected?"21433e":variant=="hover"?"253743":"17232d"),BorderColor=new Color(selected?"78ddc2":"304454"),ContentMarginLeft=7,ContentMarginRight=7,ContentMarginTop=5,ContentMarginBottom=5};if(side)style.BorderWidthLeft=selected?3:1;else style.BorderWidthBottom=selected?2:1;style.SetCornerRadiusAll(4);button.AddThemeStyleboxOverride(variant,style);}button.AddThemeColorOverride("font_pressed_color",new Color("a2f3dc"));
    }
    public void clear_fields(Control owner){owner.Set("_navigation_revision",owner.Get("_navigation_revision").AsInt64()+1);owner.Get("_sections").AsGodotDictionary().Clear();foreach(string field in new[]{"fields","section_tabs","identity_fields"}){var parent=Ui<Control>(owner,field);foreach(var child in parent.GetChildren()){parent.RemoveChild(child);child.QueueFree();}}owner.Set("_empty_section",default(Variant));foreach(string field in new[]{"main_tabs","section_scroll","identity_fields"})Ui<Control>(owner,field).Visible=false;}
    public VBoxContainer section_page(Control owner,string title,string main)
    {
        string key=main+"/"+title;var sections=owner.Get("_sections").AsGodotDictionary();if(sections.TryGetValue(key,out var existing))return existing.AsGodotDictionary()["content"].As<VBoxContainer>();var page=new VBoxContainer{Name="Section_"+title.Replace(" ","_"),Visible=false};Ui<Control>(owner,"fields").AddChild(page);page.AddChild(new Label{Text=title,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,Modulate=new Color("80dbc4")});var content=new VBoxContainer{Name="Content"};content.AddThemeConstantOverride("separation",5);page.AddChild(content);var button=new Button{Name="Category_"+title.Replace(" ","_"),Text=title,TooltipText=main+" / "+title,ToggleMode=true,Alignment=HorizontalAlignment.Left,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,Visible=false};style_navigation_button(button,true);Ui<Control>(owner,"section_tabs").AddChild(button);button.Pressed+=()=>select_section(owner,title);sections[key]=new Settings{["main"]=main,["title"]=title,["page"]=page,["content"]=content,["button"]=button};return content;
    }
    public void save_page_scroll(Control owner){var actor=owner.Get("_actor").As<Resource>();if(actor!=null&&!owner.Get("_inspecting_file").AsBool()&&!owner.Get("_restoring_scroll").AsBool())_state.set_page_scroll(Ui<Resource>(owner,"ui_state"),actor.Get("id").AsString(),owner.Get("_main_tab").AsString(),owner.Get("_section").AsString(),Ui<ScrollContainer>(owner,"content_scroll").ScrollVertical);}
    public void select_main_tab(Control owner,string title){var actor=owner.Get("_actor").As<Resource>();if(actor==null||title is not ("Actor" or "Properties"))return;save_page_scroll(owner);owner.Set("_main_tab",title);var state=Ui<Resource>(owner,"ui_state");string id=actor.Get("id").AsString();_state.set_main_tab(state,id,title);owner.Set("_section",_state.section_for(state,id,title));apply_navigation(owner);}
    public void select_section(Control owner,string title){var actor=owner.Get("_actor").As<Resource>();string main=owner.Get("_main_tab").AsString();if(actor==null||!owner.Get("_sections").AsGodotDictionary().ContainsKey(main+"/"+title))return;save_page_scroll(owner);owner.Set("_section",title);_state.set_section(Ui<Resource>(owner,"ui_state"),actor.Get("id").AsString(),main,title);apply_navigation(owner);}
    public void apply_navigation(Control owner)
    {
        owner.Set("_restoring_scroll",true);owner.Set("_navigation_revision",owner.Get("_navigation_revision").AsInt64()+1);Ui<Control>(owner,"main_tabs").Show();Ui<Control>(owner,"identity_fields").Show();string main=owner.Get("_main_tab").AsString(),section=owner.Get("_section").AsString();var pages=owner.Get("_sections").AsGodotDictionary().Values.Select(v=>v.AsGodotDictionary()).ToArray();var available=pages.Where(p=>p["main"].AsString()==main).Select(p=>p["title"].AsString()).ToArray();if(!available.Contains(section)){section=main=="Actor"&&available.Contains("Transform")?"Transform":available.FirstOrDefault()??"";owner.Set("_section",section);}var buttons=owner.Get("_main_buttons").AsGodotDictionary();foreach(var title in buttons.Keys)buttons[title].As<Button>().SetPressedNoSignal(title.AsString()==main);foreach(var page in pages){bool selected=page["main"].AsString()==main&&page["title"].AsString()==section;page["page"].As<Control>().Visible=selected;var button=page["button"].As<Button>();button.Visible=page["main"].AsString()==main;button.SetPressedNoSignal(selected);}Ui<Control>(owner,"section_scroll").Visible=available.Length>0;var empty=owner.Get("_empty_section").As<Label>();if(empty==null){empty=new Label{Text="No additional properties.",AutowrapMode=TextServer.AutowrapMode.WordSmart,Modulate=new Color("819db4")};owner.Set("_empty_section",empty);Ui<Control>(owner,"fields").AddChild(empty);}empty.Visible=available.Length==0;var actor=owner.Get("_actor").As<Resource>();if(actor!=null){string id=actor.Get("id").AsString();_state.set_section(Ui<Resource>(owner,"ui_state"),id,main,section);owner.CallDeferred("_restore_scroll",id,owner.Get("_navigation_revision"));}
    }
    public string property_main_tab(Resource property){var options=property.Get("options").AsGodotDictionary();string explicitTab=options.GetValueOrDefault("inspector_tab","").AsString();if(explicitTab is "Actor" or "Properties")return explicitTab;return property.Get("id").AsString() is "position" or "rotation" or "scale"||options.GetValueOrDefault("group","").AsString() is "Transform" or "Layout"?"Actor":"Properties";}
}
